const PREPS = ["DE","DA","DO","DAS","DOS","E"];
const CAP_MONO = 4;
const SLOTS_DIA = 7;          // slots previstos por dia
const INTERVALO_MIN = 100;    // intervalo entre slots, em minutos
const INICIO_PADRAO = '07:30';

const norm = s => String(s ?? '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .trim().toLowerCase();

function nomeCurto(nome) {
  const t = String(nome ?? '').trim().split(/\s+/);
  const primeiro = t[0];
  const resto = t.slice(1);
  if (!resto.length) return primeiro;
  if (PREPS.includes(resto[0]) && resto[1]) return `${primeiro} ${resto[0]} ${resto[1]}`;
  return `${primeiro} ${resto[0]}`;
}

const hhmm = d => String(d.Agendamento?.horario ?? '').slice(0, 5);
const ativo = d => !["Desmarcado", "Desistiu", "Faltou"].includes(d.Agendamento?.confirmado);
const ehAvaliacao = d => norm(d.Agendamento?.tipodeatendimento).includes('avaliacao');
const etiqueta = d => nomeCurto(d.Paciente?.nome) + (ehAvaliacao(d) ? ' (AVALIAÇÃO)' : '');

const paraMin = h => { const [a, b] = h.split(':').map(Number); return a * 60 + b; };
const paraHora = m => `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;

const dados = $input.all().flatMap(i =>
  Array.isArray(i.json) ? i.json : (Array.isArray(i.json.data) ? i.json.data : [i.json])
