const inicio = paraMin(observados[0] || INICIO_PADRAO);
const gradeFixa = Array.from({ length: SLOTS_DIA },
  (_, i) => paraHora(inicio + i * INTERVALO_MIN));

// horário fora da grade prevista continua aparecendo
const horarios = [...new Set([...gradeFixa, ...observados])].sort();

const grade = {};
for (let c = 1; c <= CAP_MONO; c++) grade[c] = {};

horarios.forEach(h => {
  validos
    .filter(d => hhmm(d) === h)
    .sort((a, b) => String(a.Agendamento.horario).localeCompare(String(b.Agendamento.horario)))
    .forEach((d, i) => {
      if (i < CAP_MONO) grade[i + 1][h] = etiqueta(d);
